<?php
namespace Tests\Feature;
use App\Models\{LogisticsProvider,Order,Rider,RiderCodRemittance,RiderShippingFeeEarning,Seller,SellerOrder,SellerWalletEntry,Shipment,User};
use App\Services\{CodRemittanceService,RiderShippingFeeService,SellerWalletService};
use Illuminate\Foundation\Testing\RefreshDatabase;
use Tests\TestCase;

class CodRemittanceTest extends TestCase
{
 use RefreshDatabase;
 public function test_final_rider_liability_is_unique_and_rider_submission_is_scoped_and_server_derived(): void {
  [$a,$b,$shipment]=$this->fixture(); $service=app(CodRemittanceService::class); $service->createLiability($shipment); $service->createLiability($shipment); $this->assertDatabaseCount('rider_cod_remittances',1); $row=RiderCodRemittance::first(); $this->assertSame($a['rider']->id,$row->rider_id); $this->actingAs($b['user'])->post(route('rider.cod-remittances.submit',$row),['amount'=>'1'])->assertForbidden(); $this->actingAs($a['user'])->post(route('rider.cod-remittances.submit',$row),['amount'=>'1'])->assertRedirect(); $this->assertSame(15000,$row->fresh()->submitted_minor); $this->actingAs($a['user'])->post(route('rider.cod-remittances.submit',$row))->assertSessionHasErrors();
 }
 public function test_provider_admin_and_wallet_release_are_scoped_and_idempotent(): void {
  [$a,$b,$shipment,$sellerOrder,$seller]=$this->fixture(); $svc=app(CodRemittanceService::class); $svc->createLiability($shipment); $row=RiderCodRemittance::first(); $svc->submitRider($row,$a['user']); $this->actingAs($b['providerUser'])->patch(route('logistics.cod-remittances.review',$row),['status'=>'ACCEPTED'])->assertForbidden(); $svc->reviewRider($row,$a['providerUser'],'ACCEPTED',null); $up=$svc->submitLogistics($a['providerUser'],[$row->id],null); $this->assertSame(15000,$up->expected_minor); $wallet=app(SellerWalletService::class); $wallet->creditCompleted($sellerOrder); $this->assertSame('HELD',SellerWalletEntry::where('seller_order_id',$sellerOrder->id)->first()->status); $this->actingAs($a['providerUser'])->patch(route('admin.cod-remittances.review',$up),['status'=>'ACCEPTED'])->assertForbidden(); $admin=User::factory()->create(['role'=>'admin','status'=>'active']); $svc->reviewLogistics($up,$admin,'ACCEPTED',null); $this->assertSame('AVAILABLE',SellerWalletEntry::where('seller_order_id',$sellerOrder->id)->first()->fresh()->status); $this->assertFalse($wallet->reconcileSellerOrder($sellerOrder));
 }
 public function test_final_delivery_shipping_fee_is_separate_from_full_cod_liability_and_idempotent(): void {
  [$a,$b,$shipment,$sellerOrder]=$this->fixture(); app(CodRemittanceService::class)->createLiability($shipment); app(RiderShippingFeeService::class)->creditDelivered($shipment); app(RiderShippingFeeService::class)->creditDelivered($shipment); $this->assertSame(15000,RiderCodRemittance::first()->expected_minor); $earning=RiderShippingFeeEarning::first(); $this->assertSame($a['rider']->id,$earning->rider_id); $this->assertSame(5000,$earning->amount_minor); $this->assertDatabaseCount('rider_shipping_fee_earnings',1); $shipment->update(['workflow_status'=>\App\Enums\OrderStatus::RtsCompleted]); app(RiderShippingFeeService::class)->creditDelivered($shipment); $this->assertDatabaseCount('rider_shipping_fee_earnings',1);
 }
 private function fixture(): array {
  $l1=User::factory()->create(['role'=>'logistics','status'=>'active']); $l2=User::factory()->create(['role'=>'logistics','status'=>'active']); $p1=LogisticsProvider::create(['user_id'=>$l1->id,'name'=>'P1','slug'=>'p1','status'=>'approved']); $p2=LogisticsProvider::create(['user_id'=>$l2->id,'name'=>'P2','slug'=>'p2','status'=>'approved']); $u1=User::factory()->create(['role'=>'rider','status'=>'active']); $u2=User::factory()->create(['role'=>'rider','status'=>'active']); $r1=Rider::create(['user_id'=>$u1->id,'logistics_provider_id'=>$p1->id,'vehicle_type'=>'Bike','plate_no'=>'A','is_active'=>true]); $r2=Rider::create(['user_id'=>$u2->id,'logistics_provider_id'=>$p2->id,'vehicle_type'=>'Bike','plate_no'=>'B','is_active'=>true]); $sellerUser=User::factory()->create(['role'=>'seller','status'=>'active']); $seller=Seller::create(['user_id'=>$sellerUser->id,'name'=>'S','slug'=>'s','status'=>'approved']); $buyer=User::factory()->create(['role'=>'buyer','status'=>'active']); $order=Order::create(['order_number'=>'COD-1','reference'=>'COD-1','buyer_id'=>$buyer->id,'seller_id'=>$sellerUser->id,'status'=>'COMPLETED','payment_method'=>'cod','payment_status'=>'PAID','subtotal'=>100,'shipping_fee'=>50,'discount_amount'=>0,'total_amount'=>150,'total_minor'=>15000,'recipient_name'=>'B','recipient_phone'=>'x','province'=>'x','municipality'=>'x','barangay'=>'x','street_address'=>'x','shipping_address'=>[]]); $so=SellerOrder::create(['order_id'=>$order->id,'seller_id'=>$seller->id,'subtotal_minor'=>10000,'shipping_fee_minor'=>5000,'commission_minor'=>1000,'status'=>'completed','workflow_status'=>\App\Enums\OrderStatus::Completed,'completed_at'=>now()]); $ship=Shipment::create(['seller_order_id'=>$so->id,'logistics_provider_id'=>$p1->id,'rider_id'=>$r2->id,'tracking_code'=>'COD-T','status'=>'delivered','workflow_status'=>\App\Enums\OrderStatus::Delivered,'fee_minor'=>5000,'cod_amount_minor'=>15000,'cod_collected'=>true,'cod_collected_minor'=>15000,'delivered_by'=>$u1->id,'attempts'=>0]); return [['user'=>$u1,'rider'=>$r1,'providerUser'=>$l1],['user'=>$u2,'rider'=>$r2,'providerUser'=>$l2],$ship,$so,$seller];
 }
}
